:root {
  --ink: #20302a;
  --muted: #68766f;
  --card: #fffef9;
  --line: #d9e0d4;
  --lime: #dff28b;
  --lime-ink: #36520a;
  --button: #294c3d;
  --button-ink: #ffffff;
}

.receipt-card {
  width: 440px;
  box-sizing: border-box;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--card);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 12px;
  background: var(--lime);
  font-size: 20px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  font-size: 18px;
  line-height: 1.15;
}

.status {
  margin-left: auto;
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--lime);
  color: var(--lime-ink);
  font-size: 12px;
  font-weight: 700;
}

.details {
  display: flex;
  justify-content: space-between;
  margin: 14px 0;
  padding: 10px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
}

.details p {
  margin: 0;
}

.details strong {
  color: var(--ink);
  font-size: 16px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--muted);
  font-size: 12px;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 7px 13px;
  background: var(--button);
  color: var(--button-ink);
  font-size: 13px;
  font-weight: 700;
}
